/**
 * Observability Node APIs Node for n8n — auto-generated by generate-node.ts
 * Uses n8n built-in HTTP helpers — no axios dependency.
 */
import {
  IExecuteFunctions,
  INodeExecutionData,
  INodeType,
  INodeTypeDescription,
  NodeOperationError,
  IDataObject,
  ICredentialDataDecryptedObject,
  ICredentialsDecrypted,
  ICredentialTestFunctions,
  INodeCredentialTestResult,
} from "n8n-workflow";

import { OBSERVABILITY_API_URL } from "../../credentials/ObservabilityApi.credentials";
import { executeOperation } from "./operations";
import {
  resourceSelector,
  prometheusOperations,
  prometheusFields,
  lokiOperations,
  lokiFields,
  grafanaOperations,
  grafanaFields,
  pushgatewayOperations,
  pushgatewayFields,
  meteringOperations,
  meteringFields,
} from "./resources";

/**
 * Operations that supply their own endpoint as a node parameter and therefore never
 * consult the credential's per-resource base URL. They must not be blocked when that
 * base URL is absent — see the guard in execute().
 */
const SELF_ADDRESSING_OPS = new Set(["pushLogs", "pushAAEventLog"]);

export class Observability implements INodeType {
  description: INodeTypeDescription = {
    displayName: "Observability Node APIs",
    name: "observability",
    icon: "file:observability.svg",
    group: ["transform"],
    version: [1, 2],
    subtitle: '={{$parameter["resource"] + ": " + $parameter["operation"]}}',
    description: "Query Prometheus metrics, Loki logs, Grafana and metering metrics, and push metrics to the Prometheus Pushgateway",
    defaults: { name: "Observability Node APIs" },
    inputs: ["main"],
    outputs: ["main"],
    // `testedBy` is what makes the credential test RUN. n8n resolves a
    // credential's test as: its own declarative `test`, else the `testedBy`
    // function on the node that declares the credential. A function-valued
    // `ICredentialType.test` is never called (CredentialsTester wraps it as
    // `{ testRequest: type.test }` and routes `.request` off a function, i.e.
    // undefined), which is why this module's test could never pass.
    credentials: [{ name: "observabilityApi", required: false, testedBy: "observabilityApiTest" }],
    properties: [
      resourceSelector,
      prometheusOperations,
      lokiOperations,
      grafanaOperations,
      pushgatewayOperations,
      meteringOperations,
      ...prometheusFields,
      ...lokiFields,
      ...grafanaFields,
      ...pushgatewayFields,
      ...meteringFields,
    ],
  };

  /**
   * Credential test — IMPERATIVE, and the ONLY place n8n invokes one.
   *
   * This module fronts three backends with three separate URLs, so a
   * declarative `ICredentialTestRequest` (one request) cannot express it: the
   * test probes wherever `prometheusUrl`/`baseUrl` points and, when configured,
   * Loki and Grafana too, reporting which failed. That logic used to live on the
   * credential as `async test()`, where n8n never called it.
   *
   * Resolved per backend, never across them — same rule as execute(): a missing
   * loki/grafana URL is a failure, not a silent redirect to Prometheus.
   */
  methods = {
    credentialTest: {
      async observabilityApiTest(
        this: ICredentialTestFunctions,
        credential: ICredentialsDecrypted<ICredentialDataDecryptedObject>,
      ): Promise<INodeCredentialTestResult> {
        // n8n hands the WRAPPER ({id, name, type, data}) to a node-level test —
        // unlike the credential-level one, which received the payload directly.
        const data = credential.data ?? {};
        const token = data.apiToken as string;
        const authHeaders: Record<string, string> = token
          ? { Authorization: `Bearer ${token}` }
          : {};
        const prometheusUrl =
          (data.prometheusUrl as string) || (data.baseUrl as string) || OBSERVABILITY_API_URL;
        const targets: Array<{ name: string; url: string; headers: Record<string, string> }> = [
          { name: "prometheus", url: `${prometheusUrl.replace(/\/+$/, "")}/-/healthy`, headers: authHeaders },
        ];
        if (data.lokiUrl) {
          targets.push({ name: "loki", url: `${String(data.lokiUrl).replace(/\/+$/, "")}/ready`, headers: authHeaders });
        }
        if (data.grafanaUrl) {
          targets.push({ name: "grafana", url: `${String(data.grafanaUrl).replace(/\/+$/, "")}/api/health`, headers: {} });
        }

        const failures: string[] = [];
        for (const target of targets) {
          try {
            await this.helpers.request({ method: "GET", url: target.url, headers: target.headers });
          } catch (error: any) {
            failures.push(`${target.name} (${target.url}): ${error?.message || error}`);
          }
        }
        if (failures.length > 0) {
          return { status: "Error", message: `Credential test failed — ${failures.join("; ")}` };
        }
        return {
          status: "OK",
          message: `Reachable: ${targets.map((t) => t.name).join(", ")}`,
        };
      },
    },
  };

  async execute(this: IExecuteFunctions): Promise<INodeExecutionData[][]> {
    const items = this.getInputData();
    const returnData: INodeExecutionData[] = [];

    const resource = this.getNodeParameter("resource", 0) as string;
    const operation = this.getNodeParameter("operation", 0) as string;

    let baseUrl = "";
    let headers: Record<string, string> = {};

    // Pushgateway (write surface) and Metering (reads metering's unauthenticated
    // /metrics endpoint) do not use the credential's API token — their URL is
    // supplied per-call.
    if (resource !== "pushgateway" && resource !== "metering") {
      const credentials = await this.getCredentials("observabilityApi");

      // ⛔ RESOLVE THE BASE URL PER RESOURCE, AND NEVER FALL BACK ACROSS BACKENDS.
      //
      // This used to be `baseUrl = credentials.baseUrl || OBSERVABILITY_API_URL`,
      // one value handed to every handler. Since the credential names a single
      // service and this node fronts three, that meant Loki reads and every Grafana
      // operation were addressed to Prometheus — silently, because a wrong host
      // answers with a connection error that looks exactly like an outage.
      //
      // A missing loki/grafana URL therefore THROWS rather than falling back to
      // `baseUrl`. The fallback is the bug: it is what turned "this credential is
      // not configured for Loki" into "Loki is down" for months. `prometheus` alone
      // may read `baseUrl`, because there it is the same host under an older name.
      const resourceUrl: Record<string, string> = {
        prometheus:
          (credentials.prometheusUrl as string) ||
          (credentials.baseUrl as string) ||
          OBSERVABILITY_API_URL,
        loki: (credentials.lokiUrl as string) || "",
        grafana: (credentials.grafanaUrl as string) || "",
      };
      baseUrl = (resourceUrl[resource] ?? "").replace(/\/+$/, "");
      // Only the resources this map KNOWS about are gated here. An unrecognised
      // resource must keep falling through to executeOperation's "Unknown resource:
      // <x>" — an unknown resource is not a configuration problem, and reporting it
      // as one replaces an accurate diagnosis with a misleading one.
      //
      // ⛔ AND ONLY THE OPERATIONS THAT ACTUALLY USE `baseUrl`. The ops in
      // SELF_ADDRESSING_OPS carry their own endpoint as a node parameter and have
      // NEVER read `baseUrl` — gating them on a credential URL is collateral, not
      // correction. With a credential holding only `baseUrl` and an explicit
      // `lokiUrl` on the node, `pushLogs` and `pushAAEventLog` worked on the
      // previous release and threw here, before the item loop, where
      // `continueOnFail` cannot even soften it. That is a hard break of a working
      // path, introduced by a guard aimed at a different one.
      if (
        !baseUrl &&
        Object.prototype.hasOwnProperty.call(resourceUrl, resource) &&
        !SELF_ADDRESSING_OPS.has(operation)
      ) {
        throw new NodeOperationError(
          this.getNode(),
          `No base URL configured for the "${resource}" resource. Set "${resource}Url" on the observabilityApi credential. ` +
            `It deliberately does NOT fall back to Base URL — that fallback is what sent every ${resource} request to Prometheus.`,
        );
      }

      // The token is optional: a self-hosted Prometheus, Loki or Pushgateway
      // normally needs no bearer at all, and Grafana uses its own API key. When a
      // token IS set it is sent as the bearer for whichever backend owns the
      // resource.
      const apiToken = credentials.apiToken as string;
      const tenantId = (credentials.tenantId as string) || "";
      headers = {};
      if (apiToken) {
        headers["Authorization"] = `Bearer ${apiToken}`;
      }
      // Grafana does not understand this module's API token — its API is
      // authenticated separately (only /api/health is anonymous; /api/search 401s).
      // Send the Grafana credential INSTEAD when one is set; when it is not, the
      // request still goes to the right host and Grafana's own 401 is an honest,
      // actionable answer rather than a connection reset from a service that was
      // never Grafana.
      const grafanaApiKey = (credentials.grafanaApiKey as string) || "";
      if (resource === "grafana" && grafanaApiKey) {
        headers["Authorization"] = grafanaApiKey.includes(":")
          ? `Basic ${Buffer.from(grafanaApiKey).toString("base64")}`
          : `Bearer ${grafanaApiKey}`;
      }
      // Only send X-Tenant-ID when a tenant is actually configured.
      if (tenantId) {
        headers["X-Tenant-ID"] = tenantId;
      }
    }

    for (let i = 0; i < items.length; i++) {
      try {
        const responseData = await executeOperation(this, baseUrl, headers, resource, operation, i);
        const result = responseData as IDataObject;
        if (Array.isArray(result)) {
          returnData.push(
            ...result.map((item) => ({
              json: item as IDataObject,
              pairedItem: { item: i },
            })),
          );
        } else {
          returnData.push({ json: result, pairedItem: { item: i } });
        }
      } catch (error: unknown) {
        if (this.continueOnFail()) {
          returnData.push({
            json: {
              error: error instanceof Error ? error.message : String(error),
              resource,
              operation,
            } as IDataObject,
            pairedItem: { item: i },
          });
          continue;
        }
        throw new NodeOperationError(
          this.getNode(),
          error instanceof Error ? error : new Error(String(error)),
          { itemIndex: i },
        );
      }
    }

    return [returnData];
  }
}
